func (q *Queries) TimeEntriesForChartAggregate(ctx context.Context, arg TimeEntriesForChartAggregateParams) ([]TimeEntriesForChartAggregateRow, error) {
	rows, err := q.db.Query(ctx, timeEntriesForChartAggregate,
		arg.UserID,
		arg.Column2,
		arg.OrganizationID,
		arg.Start,
		arg.Start_2,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TimeEntriesForChartAggregateRow
	for rows.Next() {
		var i TimeEntriesForChartAggregateRow
		if err := rows.Scan(&i.Date, &i.Aggregate); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

